export function useDocument(nodeId: NodeId, options: UseDocumentOptions = {}): UseDocumentReturn {
  const client = useVaulterClient()
  const debounceMs = options.debounceMs ?? 800

  const content = shallowRef<DocumentBody | null>(null)
  const head = shallowRef<DocumentContent | null>(null)
  const loading = ref(false)
  const saving = ref(false)
  const error = ref<unknown>(null)
  const conflict = shallowRef<VaulterApiError | null>(null)

  let timer: ReturnType<typeof setTimeout> | null = null
  // Saves run one at a time: a second one started while the first is in flight must carry the
  // tag the first answered, or it repeats the old one, loses the race with itself (412) and
  // can have its conflict wiped by the older success arriving late.
  let queue: Promise<unknown> = Promise.resolve()

  async function load(): Promise<DocumentContent> {
    loading.value = true
    error.value = null
    try {
      const loaded = await client.documents.content(nodeId)
      head.value = loaded
      content.value = loaded.content
      conflict.value = null
      return loaded
    } catch (caught) {
      error.value = caught
      throw caught
    } finally {
      loading.value = false
