describe('repro: upload abort during session create', () => {
  it('tus abort during the create POST leaves the session without a DELETE', async () => {
    const held = deferred<Response>()
    const calls: string[] = []
    const fetchMock = vi.fn(async (url: string, init?: RequestInit) => {
      calls.push(`${init?.method ?? 'GET'} ${url}`)
      if ((init?.method ?? 'GET') === 'POST' && String(url).endsWith('/uploads')) {
        return held.promise
      }
      return jsonResponse({ data: {} }, 204)
    })
    const client = createVaulterClient({ fetch: fetchMock as unknown as typeof fetch })
    const upload = client.uploads.start('7', new Blob(['hello']))
    const running = upload.start().then(() => 'ok', (error: unknown) => (error instanceof Error ? error.message : 'err'))
    await flush()
    await upload.abort()
    held.resolve(jsonResponse({
      data: {
        upload_id: 'u1', drive_id: '7', protocol: 'tus', status: 'initiated', received_bytes: 0,
        total_size_bytes: 5, chunk_size: 4, mime_type: null, node_id: null, target_parent_id: null,
        target_name: null, expires_at: '2027-01-01T00:00:00Z',
      },
    }, 201))
    const result = await running
    console.log('UPLOAD abort window', JSON.stringify({ result, calls }))
    expect(calls.some((c) => c.startsWith('DELETE'))).toBe(true)
  })
