describe('repro: VaulterDrive search and breadcrumb', () => {
  it('a late search repopulates results after the user cleared them and after navigation', async () => {
    const searchHeld = deferred<ReturnType<typeof pageOf>>()
    const hit = makeFile({ id: 'hit', name: 'hit.txt' })
    const folderChild = makeFile({ id: 'child', name: 'in-folder' })
    const children = vi.fn()
      .mockResolvedValueOnce(pageOf([makeFile({ id: 'root', name: 'root-file' })]))
      .mockResolvedValue(pageOf([folderChild]))
    const search = vi.fn().mockReturnValue(searchHeld.promise)
    const getWithIncludes = vi.fn().mockResolvedValue({ id: '55', breadcrumb: [{ id: '55', name: 'Folder' }] })
    const wrapper = mount(VaulterDrive, {
      props: { driveId: '7' },
      ...withClient({ nodes: { children, search, getWithIncludes } }),
    })
    await flush()
    const vm = wrapper.vm as unknown as { displayNodes: Array<{ id: string }>, goTo: (id: string | null) => Promise<void> }
    await wrapper.get('input.vaulter-drive__search').setValue('report')
    await wrapper.get('input.vaulter-drive__search').trigger('keydown', { key: 'Enter' })
    await flush()
    await wrapper.get('input.vaulter-drive__search').setValue('   ')
    await wrapper.get('input.vaulter-drive__search').trigger('keydown', { key: 'Enter' })
    await flush()
    const afterClear = vm.displayNodes.map((n) => n.id)
    searchHeld.resolve(pageOf([hit]))
    await flush()
    const afterLate = vm.displayNodes.map((n) => n.id)
    console.log('DRIVE search clear', JSON.stringify({ afterClear, afterLate }))
    expect(afterLate).toEqual(afterClear)
  })

  it('a late breadcrumb overwrites the folder the user has since opened', async () => {
    const crumbA = deferred<{ id: string, breadcrumb: Array<{ id: string, name: string }> }>()
    let crumbCalls = 0
    const children = vi.fn().mockResolvedValue(pageOf([]))
    const getWithIncludes = vi.fn().mockImplementation(() => {
      crumbCalls += 1
      if (crumbCalls === 1) return crumbA.promise
      return Promise.resolve({ id: 'B', breadcrumb: [{ id: 'B', name: 'Folder B' }] })
    })
    const wrapper = mount(VaulterDrive, {
      props: { driveId: '7' },
      ...withClient({ nodes: { children, getWithIncludes } }),
