    const toA = vm.goTo('A')
    await flush()
    const toB = vm.goTo('B')
    await flush()
    crumbA.resolve({ id: 'A', breadcrumb: [{ id: 'A', name: 'Folder A' }] })
    await Promise.all([toA, toB])
    await flush()
    const crumbs = wrapper.findAll('.vaulter-breadcrumb__crumb').map((n) => n.text())
    console.log('DRIVE breadcrumb', JSON.stringify(crumbs))
    expect(crumbs).toContain('Folder B')
    expect(crumbs).not.toContain('Folder A')
  })
})

