def mismatches(php_path, js_path, limit=40):
    found = []
    total = 0
    with open(php_path) as php, open(js_path) as js:
        for pl, jl in zip(php, js):
            total += 1
            if pl != jl:
                found.append((pl.rstrip('\n'), jl.rstrip('\n')))
                if len(found) >= limit:
